// Extends the existing cabinet; it never enables saving in preview mode.
function normalizeAdminMenu(menu){
  return {...menu,schemaVersion:2,settings:{...menu.settings,enabledPaymentMethods:Array.isArray(menu.settings?.enabledPaymentMethods)?menu.settings.enabledPaymentMethods:['card','sbp','cash','terminal'],showCourierTips:menu.settings?.showCourierTips===true},products:menu.products||[],productCategories:menu.productCategories||[{id:'groceries',name:'Продукты'}],branches:menu.branches?.length===4?menu.branches:Array.from({length:4},(_,i)=>({id:`branch-${i+1}`,name:'',address:'',phone:'',opensAt:'09:00',closesAt:'00:00',breakfastUntil:'11:00',deliveryNote:'',enabled:false,iiko:{organizationId:'',terminalGroupId:''}}))};
}
function itemInStock(item){return item.available&&(item.stock==null||item.stock>0);}
function currentItems(){return state.menu[state.page==='products'?'products':'dishes'];}
function currentCategories(){return state.menu[state.page==='products'?'productCategories':'categories'];}
function categoryItems(){return state.menu[state.categoryKind==='products'?'productCategories':'categories'];}
function categoryPage(){const product=state.categoryKind==='products',items=categoryItems();return heading('СТРУКТУРА КАТАЛОГА','Категории','Отдельные категории для блюд и товаров.','<button class="button" id="addCategory">+ Категория</button>')+`<div class="catalog-tabs" role="group" aria-label="Каталог категорий"><button class="button ${!product?'':'secondary'}" data-category-kind="dishes">Блюда</button><button class="button ${product?'':'secondary'}" data-category-kind="products">Товары</button></div><div class="category-list">${items.map((c,index)=>`<div class="category-row"><strong>${escape(c.name)}</strong><small>${state.menu[state.categoryKind].filter(d=>d.categoryId===c.id).length} позиций</small><button class="icon-button" data-move-category="${c.id}" data-direction="-1" ${!index?'disabled':''} aria-label="Поднять: ${escape(c.name)}">↑</button><button class="icon-button" data-move-category="${c.id}" data-direction="1" ${index===items.length-1?'disabled':''} aria-label="Опустить: ${escape(c.name)}">↓</button><button class="icon-button" data-category-edit="${c.id}">Изменить</button></div>`).join('')}</div>`;}
function branchesPage(){return heading('ЧЕТЫРЕ ФИЛИАЛА','Филиалы','Заполните реальные контакты, назначьте ассортимент и включите филиал.')+`<div class="branch-grid">${state.menu.branches.map((b,index)=>`<section class="panel"><span class="eyebrow">ФИЛИАЛ ${index+1}</span><h2>${escape(b.name||'Не настроен')}</h2><p>${escape(b.address||'Адрес не указан')}<br>${escape(b.phone||'Телефон не указан')}<br>${escape(b.opensAt)}–${escape(b.closesAt)} · завтраки до ${escape(b.breakfastUntil)} (Москва)</p><span class="badge ${b.enabled?'':'hidden'}">${b.enabled?'Доступен в выборе филиала':'Скрыт от гостей'}</span><p>iiko: не подключена. Заказы и доставка не отправляются.</p>${b.enabled?`<p><a href="/?branch=${b.id}" target="_blank" rel="noopener">Меню филиала ↗</a></p>`:''}<button class="button secondary" data-branch-edit="${b.id}">Настроить филиал</button></section>`).join('')}</div>`;}
function editBranch(id){const b=state.menu.branches.find(b=>b.id===id);dialog.innerHTML=dialogHead('Настройки филиала')+`<form id="branchForm" data-id="${b.id}"><div class="form-grid">${[['name','Название',120],['address','Адрес',180],['phone','Телефон',80]].map(([key,label,max])=>`<label class="field full">${label}<input name="${key}" maxlength="${max}" value="${escape(b[key])}"></label>`).join('')}${[['opensAt','Открытие'],['closesAt','Закрытие'],['breakfastUntil','Завтраки до']].map(([key,label])=>`<label class="field">${label}<input type="time" name="${key}" value="${escape(b[key])}" required></label>`).join('')}<label class="field full">Условия доставки<textarea name="deliveryNote" maxlength="600">${escape(b.deliveryNote)}</textarea><small>Правило «от 1000 ₽ доставка» ещё требует уточнения. Не указывайте предположения.</small></label></div><p class="catalog-note">Время указано по Москве. Закрытие в 00:00 означает полночь. Приём заказов пока не подключён.</p><label class="check"><input type="checkbox" name="enabled" ${b.enabled?'checked':''}>Показывать филиал гостям (нужны название и адрес)</label><section class="panel integration-panel"><h2>iiko · не подключена</h2><p>Можно сохранить идентификаторы для будущего подключения. Реквизиты и проверка авторизации доступны в разделе «Подключения». Импорт и отправка заказов пока недоступны.</p>${[['organizationId','ID организации'],['terminalGroupId','ID терминальной группы']].map(([key,label])=>`<label class="field">${label}<input name="${key}" maxlength="120" value="${escape(b.iiko?.[key]||'')}"></label>`).join('')}</section><p class="error-text" id="formError" role="alert"></p><div class="dialog-actions"><button class="button secondary" type="button" id="cancelEditor">Отмена</button><button class="button" type="submit">Применить</button></div></form>`;dialog.showModal();dialog.querySelector('[name=name]').focus();}
function applyBranchForm(form){const value=name=>form.elements[name].value.trim();const enabled=form.elements.enabled.checked;if(enabled&&(!value('name')||!value('address')))throw new Error('Для включения филиала укажите название и адрес.');const index=state.menu.branches.findIndex(b=>b.id===form.dataset.id);state.menu.branches[index]={id:form.dataset.id,...Object.fromEntries(['name','address','phone','opensAt','closesAt','breakfastUntil','deliveryNote'].map(key=>[key,value(key)])),enabled,iiko:{organizationId:value('organizationId'),terminalGroupId:value('terminalGroupId')}};}
function itemExtraFields(item,product){return product?`<div class="form-grid"><label class="field">Единица цены<select name="unit">${['шт','кг','л'].map(unit=>`<option value="${unit}" ${unit===item.unit?'selected':''}>${unit}</option>`).join('')}</select></label><label class="field">Остаток<input name="stock" type="number" min="0" max="1000000" step="0.001" value="${item.stock??''}"><small>Пусто — не указан; 0 — недоступно. Учёт списаний не подключён.</small></label></div>`:`<label class="check"><input name="breakfast" type="checkbox" ${item.breakfast?'checked':''}>Завтрак · доступен до времени, заданного филиалом (Москва)</label>`;}
function branchItemFields(item,product){return `<fieldset class="branch-assignments"><legend>Ассортимент и цены филиалов</legend><p class="catalog-note">Позиция видна в филиале только после назначения. Пустая цена — общая цена. Общий стоп-лист и скрытие действуют во всех филиалах.</p>${state.menu.branches.map((b,index)=>{const o=item.branchOverrides?.[b.id]||{assigned:false,published:true,available:true,price:null,stock:null};return `<div class="assignment"><strong>${escape(b.name||`Филиал ${index+1} · не настроен`)}</strong><div class="checks"><label class="check"><input type="checkbox" name="${b.id}-assigned" ${o.assigned?'checked':''}>В ассортименте</label><label class="check"><input type="checkbox" name="${b.id}-published" ${o.published?'checked':''}>Показывать</label><label class="check"><input type="checkbox" name="${b.id}-available" ${o.available?'checked':''}>В наличии</label></div><div class="form-grid"><label class="field">Цена филиала, ₽<input type="number" name="${b.id}-price" min="0" max="100000" step="0.01" value="${o.price??''}" placeholder="Общая цена"></label>${product?`<label class="field">Остаток филиала<input type="number" name="${b.id}-stock" min="0" max="1000000" step="0.001" value="${o.stock??''}" placeholder="Общий остаток"></label>`:''}</div></div>`;}).join('')}</fieldset>`;}
function extraItemValues(form,product){const nullable=name=>form.elements[name].value.trim()===''?null:Number(form.elements[name].value);return {...(product?{unit:form.elements.unit.value,stock:nullable('stock')}:{breakfast:form.elements.breakfast.checked}),branchOverrides:Object.fromEntries(state.menu.branches.map(b=>[b.id,{assigned:form.elements[b.id+'-assigned'].checked,published:form.elements[b.id+'-published'].checked,available:form.elements[b.id+'-available'].checked,price:nullable(b.id+'-price'),...(product?{stock:nullable(b.id+'-stock')}:{})}]))};}
async function importPrices(){if(!confirm('Добавить недостающие блюда из TXT в черновик? Существующие позиции и их цены не изменятся. Неоднозначная строка «баранина 450р» пропущена.'))return;const source=state.preview?await (await fetch('/api/catalog',{cache:'no-store'})).json():await request('price-list');let count=0;for(const item of source.dishes){if(state.menu.dishes.some(d=>d.id===item.id))continue;const category=source.categories.find(c=>c.id===item.categoryId);if(!state.menu.categories.some(c=>c.id===category.id))state.menu.categories.push(category);state.menu.dishes.push({...item});count++;}if(count){setDirty();render();}notify(count?`В черновик добавлено ${count} позиций. Существующие цены сохранены.`:'Все позиции из TXT уже есть в каталоге.');}
